<script>
(function() {
  // ========== HEADER SCROLL SHADOW ==========
  const header = document.getElementById('header');
  window.addEventListener('scroll', function() {
    header.classList.toggle('scrolled', window.scrollY > 10);
  });

  // ========== HAMBURGER MENU ==========
  const hamburger = document.getElementById('hamburger');
  const overlay = document.getElementById('mobileOverlay');
  let menuOpen = false;

  function openMenu() {
    menuOpen = true;
    hamburger.classList.add('active');
    overlay.classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  function closeMenu() {
    menuOpen = false;
    hamburger.classList.remove('active');
    overlay.classList.remove('active');
    document.body.style.overflow = '';
  }

  hamburger.addEventListener('click', function() {
    menuOpen ? closeMenu() : openMenu();
  });

  overlay.querySelectorAll('a').forEach(function(link) {
    link.addEventListener('click', closeMenu);
  });

  // ========== NEWS CAROUSEL ==========
  var carousel = document.getElementById('newsCarousel');
  var prevBtn = document.getElementById('carouselPrev');
  var nextBtn = document.getElementById('carouselNext');

  function getScrollAmount() {
    var card = carousel.querySelector('.news-card');
    if (!card) return 340;
    var style = getComputedStyle(carousel);
    var gap = parseInt(style.columnGap) || parseInt(style.gap) || 20;
    return card.offsetWidth + gap;
  }

  function scrollCarousel(direction) {
    var amount = getScrollAmount();
    carousel.scrollBy({
      left: direction * amount,
      behavior: 'smooth'
    });
  }

  nextBtn.addEventListener('click', function() { scrollCarousel(1); });
  prevBtn.addEventListener('click', function() { scrollCarousel(-1); });

  // Keyboard navigation for carousel
  carousel.addEventListener('keydown', function(e) {
    if (e.key === 'ArrowRight') { e.preventDefault(); scrollCarousel(1); }
    if (e.key === 'ArrowLeft') { e.preventDefault(); scrollCarousel(-1); }
  });

  // Touch/swipe for carousel
  var touchStartX = 0;
  var touchEndX = 0;

  carousel.addEventListener('touchstart', function(e) {
    touchStartX = e.changedTouches[0].screenX;
  }, { passive: true });

  carousel.addEventListener('touchend', function(e) {
    touchEndX = e.changedTouches[0].screenX;
    var diff = touchStartX - touchEndX;
    if (Math.abs(diff) > 50) {
      scrollCarousel(diff > 0 ? 1 : -1);
    }
  });

  // ========== SCROLL ANIMATIONS ==========
  var fadeEls = document.querySelectorAll('.fade-in');

  function checkFadeIn() {
    var windowHeight = window.innerHeight;
    fadeEls.forEach(function(el) {
      var rect = el.getBoundingClientRect();
      if (rect.top < windowHeight - 80) {
        el.classList.add('visible');
      }
    });
  }

  // Trigger immediately for elements in view on load
  checkFadeIn();
  window.addEventListener('scroll', checkFadeIn, { passive: true });

  // ========== SMOOTH SCROLL FOR NAV LINKS ==========
  document.querySelectorAll('a[href^="#"]').forEach(function(anchor) {
    anchor.addEventListener('click', function(e) {
      var target = document.querySelector(this.getAttribute('href'));
      if (target) {
        e.preventDefault();
        var offset = header.offsetHeight + 16;
        var top = target.getBoundingClientRect().top + window.pageYOffset - offset;
        window.scrollTo({ top: top, behavior: 'smooth' });
      }
    });
  });
})();
</script>

